import React, { useState } from 'react';
import { Product, CartItem } from './data';
import { theme } from './theme';
import Hero from './components/Hero';
import Categories from './components/Categories';
import ProductGrid from './components/ProductGrid';
import Cart from './components/Cart';
import Footer from './components/Footer';
import { ShoppingCart, Search } from 'lucide-react';

export default function App() {
  const [cartItems, setCartItems] = useState<CartItem[]>([]);
  const [cartOpen, setCartOpen] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');

  const addToCart = (product: Product) => {
    setCartItems(prev => {
      const existing = prev.find(i => i.product.id === product.id);
      if (existing) return prev.map(i => i.product.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { product, quantity: 1 }];
    });
    setCartOpen(true);
  };

  const removeFromCart = (id: string) => setCartItems(prev => prev.filter(i => i.product.id !== id));

  const updateQuantity = (id: string, qty: number) => {
    if (qty === 0) { removeFromCart(id); return; }
    setCartItems(prev => prev.map(i => i.product.id === id ? { ...i, quantity: qty } : i));
  };

  const totalItems = cartItems.reduce((s, i) => s + i.quantity, 0);

  return (
    <div style={{ fontFamily: theme.fontFamily, background: theme.colors.bg, minHeight: '100vh' }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');
        * { box-sizing: border-box; margin: 0; padding: 0; }
        body { overflow-x: hidden; }
        ::-webkit-scrollbar { width: 6px; }
        ::-webkit-scrollbar-thumb { background: #16a34a; border-radius: 3px; }
      `}</style>

      {/* Navbar */}
      <nav style={{
        position: 'sticky', top: 0, zIndex: 100,
        background: 'rgba(255,255,255,0.96)', backdropFilter: 'blur(20px)',
        borderBottom: '1px solid rgba(0,0,0,0.07)', padding: '0 2rem',
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        height: '68px', boxShadow: '0 2px 16px rgba(0,0,0,0.05)',
      }}>
        {/* Logo */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px', flexShrink: 0 }}>
          <div style={{ width: '38px', height: '38px', background: 'linear-gradient(135deg, #16a34a, #4ade80)', borderRadius: '10px', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '18px', boxShadow: '0 4px 10px rgba(22,163,74,0.3)' }}>🛒</div>
          <span style={{ fontSize: '1.45rem', fontWeight: 900, color: '#14532d', letterSpacing: '-0.5px' }}>
            Fresh<span style={{ color: '#16a34a' }}>Mart</span>
          </span>
        </div>

        {/* Search */}
        <div style={{ flex: 1, maxWidth: '500px', margin: '0 2rem', position: 'relative' }}>
          <Search size={17} style={{ position: 'absolute', left: '14px', top: '50%', transform: 'translateY(-50%)', color: '#94a3b8', pointerEvents: 'none' }} />
          <input type="text" placeholder="Buscar productos..."
            value={searchQuery} onChange={e => setSearchQuery(e.target.value)}
            style={{ width: '100%', padding: '10px 16px 10px 40px', border: '2px solid #e2e8f0', borderRadius: '50px', fontSize: '0.9rem', outline: 'none', fontFamily: theme.fontFamily, background: '#f8fafc', transition: 'all 0.2s', color: '#0f172a' }}
            onFocus={e => { e.target.style.borderColor = '#16a34a'; e.target.style.background = 'white'; }}
            onBlur={e => { e.target.style.borderColor = '#e2e8f0'; e.target.style.background = '#f8fafc'; }}
          />
        </div>

        {/* Cart */}
        <button onClick={() => setCartOpen(true)} style={{ position: 'relative', background: 'linear-gradient(135deg, #16a34a, #15803d)', color: 'white', border: 'none', borderRadius: '50px', padding: '10px 22px', fontSize: '0.9rem', fontWeight: 700, cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '8px', boxShadow: '0 4px 14px rgba(22,163,74,0.3)', transition: 'transform 0.2s, box-shadow 0.2s', fontFamily: theme.fontFamily, flexShrink: 0 }}
          onMouseEnter={e => { (e.currentTarget as HTMLButtonElement).style.transform = 'translateY(-2px)'; (e.currentTarget as HTMLButtonElement).style.boxShadow = '0 8px 20px rgba(22,163,74,0.4)'; }}
          onMouseLeave={e => { (e.currentTarget as HTMLButtonElement).style.transform = 'translateY(0)'; (e.currentTarget as HTMLButtonElement).style.boxShadow = '0 4px 14px rgba(22,163,74,0.3)'; }}>
          <ShoppingCart size={18} />
          Carrito
          {totalItems > 0 && (
            <span style={{ position: 'absolute', top: '-7px', right: '-7px', background: '#f97316', color: 'white', borderRadius: '50%', width: '22px', height: '22px', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '0.72rem', fontWeight: 800 }}>
              {totalItems}
            </span>
          )}
        </button>
      </nav>

      <Hero />
      <Categories selected={selectedCategory} onSelect={setSelectedCategory} />
      <ProductGrid
        selectedCategory={selectedCategory}
        searchQuery={searchQuery}
        cartItems={cartItems}
        onAddToCart={addToCart}
        onUpdateQuantity={updateQuantity}
      />
      <Footer />
      <Cart isOpen={cartOpen} onClose={() => setCartOpen(false)} items={cartItems} onUpdateQuantity={updateQuantity} onRemove={removeFromCart} />
    </div>
  );
}

