import React from 'react';
import { CartItem } from '../data';
import { X, Minus, Plus, ShoppingBag, Trash2 } from 'lucide-react';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  items: CartItem[];
  onUpdateQuantity: (id: string, qty: number) => void;
  onRemove: (id: string) => void;
}

export default function Cart({ isOpen, onClose, items, onUpdateQuantity, onRemove }: Props) {
  const total = items.reduce((sum, i) => sum + i.product.price * i.quantity, 0);
  const itemCount = items.reduce((sum, i) => sum + i.quantity, 0);
  const freeShipping = total >= 20000;
  const remaining = 20000 - total;

  return (
    <>
      {/* Overlay */}
      <div onClick={onClose} style={{
        position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.4)', backdropFilter: 'blur(4px)',
        zIndex: 200, opacity: isOpen ? 1 : 0, pointerEvents: isOpen ? 'all' : 'none',
        transition: 'opacity 0.3s',
      }} />

      {/* Drawer */}
      <div style={{
        position: 'fixed', top: 0, right: 0, bottom: 0, width: '420px', maxWidth: '95vw',
        background: 'white', zIndex: 201, display: 'flex', flexDirection: 'column',
        transform: isOpen ? 'translateX(0)' : 'translateX(100%)', transition: 'transform 0.35s cubic-bezier(0.4,0,0.2,1)',
        boxShadow: '-8px 0 40px rgba(0,0,0,0.15)',
      }}>
        {/* Header */}
        <div style={{ padding: '1.5rem', borderBottom: '1px solid #f1f5f9', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <ShoppingBag size={22} color="#16a34a" />
            <span style={{ fontSize: '1.2rem', fontWeight: 800, color: '#0f172a' }}>Mi Carrito</span>
            {itemCount > 0 && <span style={{ background: '#16a34a', color: 'white', borderRadius: '50px', padding: '2px 10px', fontSize: '0.8rem', fontWeight: 700 }}>{itemCount}</span>}
          </div>
          <button onClick={onClose} style={{ width: '36px', height: '36px', borderRadius: '50%', background: '#f1f5f9', border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#475569' }}>
            <X size={18} />
          </button>
        </div>

        {/* Free shipping bar */}
        {items.length > 0 && (
          <div style={{ padding: '12px 1.5rem', background: freeShipping ? '#f0fdf4' : '#fffbeb', borderBottom: '1px solid #f1f5f9' }}>
            {freeShipping ? (
              <p style={{ fontSize: '0.83rem', color: '#16a34a', fontWeight: 600 }}>🎉 ¡Tienes despacho gratis!</p>
            ) : (
              <div>
                <p style={{ fontSize: '0.83rem', color: '#92400e', fontWeight: 600, marginBottom: '6px' }}>
                  Te faltan ${remaining.toLocaleString('es-CL')} para despacho gratis
                </p>
                <div style={{ height: '6px', background: '#e2e8f0', borderRadius: '3px', overflow: 'hidden' }}>
                  <div style={{ height: '100%', width: `${Math.min(100, (total / 20000) * 100)}%`, background: 'linear-gradient(90deg, #16a34a, #4ade80)', borderRadius: '3px', transition: 'width 0.4s' }} />
                </div>
              </div>
            )}
          </div>
        )}

        {/* Items */}
        <div style={{ flex: 1, overflowY: 'auto', padding: '1rem 1.5rem' }}>
          {items.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '4rem 0', color: '#94a3b8' }}>
              <div style={{ fontSize: '4rem', marginBottom: '1rem' }}>🛒</div>
              <h3 style={{ fontWeight: 700, color: '#475569', marginBottom: '0.5rem' }}>Tu carrito está vacío</h3>
              <p style={{ fontSize: '0.9rem' }}>Agrega productos para comenzar</p>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
              {items.map(item => (
                <div key={item.product.id} style={{ display: 'flex', gap: '12px', padding: '12px', background: '#f8fafc', borderRadius: '16px', border: '1px solid #f1f5f9' }}>
                  <img src={item.product.image} alt={item.product.name} style={{ width: '70px', height: '70px', objectFit: 'cover', borderRadius: '12px' }} />
                  <div style={{ flex: 1 }}>
                    <p style={{ fontWeight: 700, fontSize: '0.9rem', color: '#0f172a', marginBottom: '2px' }}>{item.product.name}</p>
                    <p style={{ fontSize: '0.78rem', color: '#94a3b8', marginBottom: '8px' }}>{item.product.unit}</p>
                    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '8px', background: 'white', borderRadius: '50px', padding: '4px', border: '1px solid #e2e8f0' }}>
                        <button onClick={() => onUpdateQuantity(item.product.id, item.quantity - 1)}
                          style={{ width: '26px', height: '26px', borderRadius: '50%', background: '#f1f5f9', border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#475569' }}>
                          <Minus size={13} />
                        </button>
                        <span style={{ fontSize: '0.9rem', fontWeight: 700, color: '#0f172a', minWidth: '20px', textAlign: 'center' }}>{item.quantity}</span>
                        <button onClick={() => onUpdateQuantity(item.product.id, item.quantity + 1)}
                          style={{ width: '26px', height: '26px', borderRadius: '50%', background: '#16a34a', border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white' }}>
                          <Plus size={13} />
                        </button>
                      </div>
                      <span style={{ fontWeight: 800, color: '#14532d', fontSize: '1rem' }}>
                        ${(item.product.price * item.quantity).toLocaleString('es-CL')}
                      </span>
                    </div>
                  </div>
                  <button onClick={() => onRemove(item.product.id)}
                    style={{ alignSelf: 'flex-start', width: '30px', height: '30px', borderRadius: '8px', background: '#fef2f2', border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#dc2626' }}>
                    <Trash2 size={14} />
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Footer */}
        {items.length > 0 && (
          <div style={{ padding: '1.5rem', borderTop: '1px solid #f1f5f9', background: 'white' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.5rem' }}>
              <span style={{ color: '#64748b' }}>Subtotal</span>
              <span style={{ fontWeight: 600 }}>${total.toLocaleString('es-CL')}</span>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '1.25rem' }}>
              <span style={{ color: '#64748b' }}>Despacho</span>
              <span style={{ fontWeight: 600, color: freeShipping ? '#16a34a' : '#0f172a' }}>{freeShipping ? 'Gratis 🎉' : '$2.990'}</span>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '1.5rem', paddingTop: '0.75rem', borderTop: '2px solid #f1f5f9' }}>
              <span style={{ fontWeight: 800, fontSize: '1.1rem' }}>Total</span>
              <span style={{ fontWeight: 800, fontSize: '1.3rem', color: '#14532d' }}>
                ${(total + (freeShipping ? 0 : 2990)).toLocaleString('es-CL')}
              </span>
            </div>
            <button style={{ width: '100%', padding: '15px', background: 'linear-gradient(135deg, #16a34a, #15803d)', color: 'white', border: 'none', borderRadius: '50px', fontSize: '1rem', fontWeight: 700, cursor: 'pointer', boxShadow: '0 6px 20px rgba(22,163,74,0.35)', transition: 'opacity 0.2s' }}
              onMouseEnter={e => { (e.currentTarget as HTMLButtonElement).style.opacity = '0.92'; }}
              onMouseLeave={e => { (e.currentTarget as HTMLButtonElement).style.opacity = '1'; }}>
              Ir a pagar →
            </button>
          </div>
        )}
      </div>
    </>
  );
}

