import React from 'react';
import { categories, Category } from '../data';

interface Props {
  selected: string;
  onSelect: (id: string) => void;
}

export default function Categories({ selected, onSelect }: Props) {
  return (
    <section style={{ background: 'white', borderBottom: '1px solid #e2e8f0', padding: '0 2rem' }}>
      <div style={{ maxWidth: '1200px', margin: '0 auto', display: 'flex', gap: '0', overflowX: 'auto', scrollbarWidth: 'none' }}>
        {categories.map((cat: Category) => {
          const active = selected === cat.id;
          return (
            <button key={cat.id} onClick={() => onSelect(cat.id)}
              style={{
                display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '6px',
                padding: '20px 22px', border: 'none', background: 'transparent', cursor: 'pointer',
                borderBottom: active ? `3px solid ${cat.color}` : '3px solid transparent',
                color: active ? cat.color : '#64748b',
                fontWeight: active ? 700 : 500, fontSize: '0.8rem', whiteSpace: 'nowrap',
                transition: 'all 0.2s', minWidth: 'fit-content', position: 'relative',
              }}
              onMouseEnter={e => { if (!active) (e.currentTarget as HTMLButtonElement).style.color = cat.color; }}
              onMouseLeave={e => { if (!active) (e.currentTarget as HTMLButtonElement).style.color = '#64748b'; }}
            >
              <span style={{ fontSize: '1.6rem', lineHeight: 1, filter: active ? 'none' : 'grayscale(30%)' }}>{cat.icon}</span>
              <span>{cat.name}</span>
            </button>
          );
        })}
      </div>
    </section>
  );
}

