import React, { useState, useEffect, useRef } from 'react';
import { heroSlides } from '../data';

export default function Hero() {
  const [current, setCurrent] = useState(0);
  const [fading, setFading] = useState(false);
  const mounted = useRef(true);

  useEffect(() => {
    mounted.current = true;
    const timer = setInterval(() => {
      if (!mounted.current) return;
      setFading(true);
      setTimeout(() => {
        if (!mounted.current) return;
        setCurrent(prev => (prev + 1) % heroSlides.length);
        setFading(false);
      }, 400);
    }, 5000);
    return () => { mounted.current = false; clearInterval(timer); };
  }, []);

  const goTo = (idx: number) => {
    if (idx === current || fading) return;
    setFading(true);
    setTimeout(() => {
      if (!mounted.current) return;
      setCurrent(idx);
      setFading(false);
    }, 300);
  };

  const slide = heroSlides[current];

  return (
    <section style={{ position: 'relative', overflow: 'hidden', minHeight: '540px', background: slide.bg, transition: 'background 0.8s ease' }}>
      <div style={{ position: 'absolute', inset: 0, backgroundImage: `radial-gradient(ellipse at 75% 50%, ${slide.accent}18 0%, transparent 65%)`, pointerEvents: 'none' }} />
      <div style={{ position: 'absolute', top: '-80px', right: '-80px', width: '400px', height: '400px', borderRadius: '50%', background: `${slide.accent}08`, pointerEvents: 'none' }} />

      <div style={{ maxWidth: '1200px', margin: '0 auto', padding: '4rem 2rem', display: 'flex', alignItems: 'center', gap: '3rem', position: 'relative', zIndex: 1, minHeight: '540px' }}>
        {/* Left content */}
        <div style={{ flex: 1, opacity: fading ? 0 : 1, transform: fading ? 'translateY(16px)' : 'translateY(0)', transition: 'all 0.4s ease' }}>
          <div style={{ display: 'inline-flex', alignItems: 'center', gap: '6px', background: `${slide.accent}20`, border: `1px solid ${slide.accent}40`, borderRadius: '50px', padding: '6px 14px', fontSize: '0.82rem', fontWeight: 600, color: slide.accent, marginBottom: '1.5rem' }}>
            {slide.badge}
          </div>
          <h1 style={{ fontSize: 'clamp(2.2rem, 5vw, 3.8rem)', fontWeight: 900, color: 'white', lineHeight: 1.08, marginBottom: '1rem', letterSpacing: '-1.5px' }}>
            {slide.title}<br />
            <span style={{ color: slide.accent }}>{slide.highlight}</span>
          </h1>
