import React from 'react';
import { Product, CartItem } from '../data';
import { ShoppingCart, Star, Plus, Minus } from 'lucide-react';

const BADGE_COLORS: Record<string, { bg: string; color: string }> = {
  'Oferta':   { bg: '#fef2f2', color: '#dc2626' },
  'Nuevo':    { bg: '#f0fdf4', color: '#16a34a' },
  'Popular':  { bg: '#fff7ed', color: '#ea580c' },
  'Orgánico': { bg: '#f7fee7', color: '#65a30d' },
};

interface Props {
  product: Product;
  cartItem?: CartItem;
  onAdd: (p: Product) => void;
  onUpdate: (id: string, qty: number) => void;
}

export default function ProductCard({ product, cartItem, onAdd, onUpdate }: Props) {
  const discount = product.originalPrice
    ? Math.round((1 - product.originalPrice / product.originalPrice) * 100)
    : null;
  const pct = product.originalPrice
    ? Math.round((1 - product.price / product.originalPrice) * 100)
    : null;
  const badge = product.badge ? BADGE_COLORS[product.badge] : null;

  return (
    <div style={{
      background: 'white', borderRadius: '20px', overflow: 'hidden',
      boxShadow: '0 2px 12px rgba(0,0,0,0.06)', border: '1px solid #f1f5f9',
      transition: 'transform 0.22s, box-shadow 0.22s', display: 'flex', flexDirection: 'column',
    }}
      onMouseEnter={e => { (e.currentTarget as HTMLDivElement).style.transform = 'translateY(-4px)'; (e.currentTarget as HTMLDivElement).style.boxShadow = '0 12px 28px rgba(0,0,0,0.12)'; }}
      onMouseLeave={e => { (e.currentTarget as HTMLDivElement).style.transform = 'translateY(0)'; (e.currentTarget as HTMLDivElement).style.boxShadow = '0 2px 12px rgba(0,0,0,0.06)'; }}
    >
      {/* Image */}
      <div style={{ position: 'relative', height: '180px', overflow: 'hidden', background: '#f8fafc' }}>
        <img src={product.image} alt={product.name}
          style={{ width: '100%', height: '100%', objectFit: 'cover', transition: 'transform 0.4s' }}
          onMouseEnter={e => { (e.currentTarget as HTMLImageElement).style.transform = 'scale(1.06)'; }}
          onMouseLeave={e => { (e.currentTarget as HTMLImageElement).style.transform = 'scale(1)'; }}
        />
        {badge && (
          <span style={{ position: 'absolute', top: '10px', left: '10px', background: badge.bg, color: badge.color, fontSize: '0.72rem', fontWeight: 700, padding: '3px 10px', borderRadius: '50px', border: `1px solid ${badge.color}30` }}>
            {product.badge}
          </span>
        )}
        {pct && (
          <span style={{ position: 'absolute', top: '10px', right: '10px', background: '#dc2626', color: 'white', fontSize: '0.72rem', fontWeight: 700, padding: '3px 8px', borderRadius: '8px' }}>
            -{pct}%
          </span>
        )}
      </div>

      {/* Body */}
      <div style={{ padding: '14px 16px', flex: 1, display: 'flex', flexDirection: 'column', gap: '8px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
          <Star size={13} color="#f59e0b" fill="#f59e0b" />
          <span style={{ fontSize: '0.78rem', fontWeight: 600, color: '#0f172a' }}>{product.rating}</span>
          <span style={{ fontSize: '0.72rem', color: '#94a3b8' }}>({product.reviews})</span>
        </div>
        <h3 style={{ fontSize: '0.95rem', fontWeight: 700, color: '#0f172a', lineHeight: 1.3 }}>{product.name}</h3>
        <span style={{ fontSize: '0.78rem', color: '#94a3b8' }}>{product.unit}</span>
        <div style={{ display: 'flex', alignItems: 'baseline', gap: '8px', marginTop: 'auto' }}>
          <span style={{ fontSize: '1.2rem', fontWeight: 800, color: '#14532d' }}>
            ${product.price.toLocaleString('es-CL')}
          </span>
          {product.originalPrice && (
            <span style={{ fontSize: '0.85rem', color: '#94a3b8', textDecoration: 'line-through' }}>
              ${product.originalPrice.toLocaleString('es-CL')}
            </span>
          )}
        </div>
      </div>

      {/* Cart action */}
      <div style={{ padding: '0 16px 16px' }}>
        {cartItem ? (
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', background: '#f0fdf4', borderRadius: '50px', padding: '6px' }}>
            <button onClick={() => onUpdate(product.id, cartItem.quantity - 1)}
              style={{ width: '34px', height: '34px', borderRadius: '50%', background: 'white', border: '1px solid #bbf7d0', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#16a34a' }}>
              <Minus size={16} />
            </button>
            <span style={{ fontWeight: 700, color: '#14532d', fontSize: '1rem' }}>{cartItem.quantity}</span>
            <button onClick={() => onUpdate(product.id, cartItem.quantity + 1)}
              style={{ width: '34px', height: '34px', borderRadius: '50%', background: '#16a34a', border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white' }}>
              <Plus size={16} />
            </button>
          </div>
        ) : (
          <button onClick={() => onAdd(product)}
            style={{ width: '100%', padding: '10px', background: 'linear-gradient(135deg, #16a34a, #15803d)', color: 'white', border: 'none', borderRadius: '50px', fontSize: '0.88rem', fontWeight: 600, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '6px', transition: 'opacity 0.2s' }}
            onMouseEnter={e => { (e.currentTarget as HTMLButtonElement).style.opacity = '0.9'; }}
            onMouseLeave={e => { (e.currentTarget as HTMLButtonElement).style.opacity = '1'; }}>
            <ShoppingCart size={16} /> Agregar
          </button>
        )}
      </div>
    </div>
  );
}

components/ProductGrid.tsx.content:
import React from 'react';
import { products, categories, Product, CartItem } from '../data';
import ProductCard from './ProductCard';
import { Search } from 'lucide-react';

interface Props {
  selectedCategory: string;
  searchQuery: string;
  cartItems: CartItem[];
  onAddToCart: (p: Product) => void;
  onUpdateQuantity: (id: string, qty: number) => void;
}

export default function ProductGrid({ selectedCategory, searchQuery, cartItems, onAddToCart, onUpdateQuantity }: Props) {
  const filtered = products.filter(p => {
    const matchCat = selectedCategory === 'all' || p.category === selectedCategory;
    const matchSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase());
    return matchCat && matchSearch;
  });

  const catLabel = categories.find(c => c.id === selectedCategory)?.name ?? 'Todos los productos';

  return (
    <section style={{ maxWidth: '1200px', margin: '0 auto', padding: '3rem 2rem' }}>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '2rem', flexWrap: 'wrap', gap: '1rem' }}>
        <div>
          <h2 style={{ fontSize: '1.8rem', fontWeight: 800, color: '#0f172a', letterSpacing: '-0.5px' }}>{catLabel}</h2>
          <p style={{ color: '#64748b', marginTop: '4px' }}>{filtered.length} producto{filtered.length !== 1 ? 's' : ''} encontrado{filtered.length !== 1 ? 's' : ''}</p>
        </div>
        {searchQuery && (
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px', background: '#f0fdf4', padding: '8px 16px', borderRadius: '50px', color: '#16a34a', fontSize: '0.88rem', fontWeight: 600 }}>
            <Search size={15} />
            Resultados para: "{searchQuery}"
          </div>
        )}
      </div>

      {filtered.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '5rem 0', color: '#94a3b8' }}>
          <div style={{ fontSize: '4rem', marginBottom: '1rem' }}>🔍</div>
          <h3 style={{ fontSize: '1.3rem', fontWeight: 700, marginBottom: '0.5rem', color: '#475569' }}>No encontramos productos</h3>
          <p>Intenta con otro término o categoría</p>
        </div>
      ) : (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(220px, 1fr))', gap: '1.25rem' }}>
          {filtered.map(product => (
            <ProductCard
              key={product.id}
              product={product}
              cartItem={cartItems.find(i => i.product.id === product.id)}
              onAdd={onAddToCart}
              onUpdate={onUpdateQuantity}
            />
          ))}
        </div>
      )}
    </section>
  );
}

